{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Subjects have received prior docetaxel in unresectable or metastatic setting (including subjects who received prior docetaxel in first line for metastatic disease, but not including subjects who received prior docetaxel neoadjuvantly or adjuvantly and did not progress within 6 months of end of therapy).",
      "quote": "Subjects have received prior docetaxel in unresectable or metastatic setting",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Mixed small-cell lung cancer or mixed NSCLC histology",
      "quote": "Mixed small-cell lung cancer or mixed NSCLC histology",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Previously identified driver mutation (according to local standard of care or guidelines) other than KRAS p.G12C for which an approved therapy is available (including EGFR, ALK, etc).",
      "quote": "Previously identified driver mutation (according to local standard of care or guidelines) other than KRAS p.G12C for which an approved therapy is available",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Active brain metastases. Active brain metastases are defined as: Untreated brain lesions (new or progressing) and/or symptomatic brain lesions (symptoms as determined by the investigator), present at the time of study entry.",
      "quote": "Active brain metastases are defined as: Untreated brain lesions (new or progressing) and/or symptomatic brain lesions",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Leptomeningeal disease.",
      "quote": "Leptomeningeal disease.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Uncontrolled pleural effusion, pericardial effusion, or ascites requiring recurrent drainage procedures at a frequency greater than monthly. Subjects with PleurX catheters in place may be considered for the study with Medical Monitor approval.",
      "quote": "Uncontrolled pleural effusion, pericardial effusion, or ascites requiring recurrent drainage procedures at a frequency greater than monthly.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known history of Human Immunodeficiency Virus (HIV) infection",
      "quote": "Known history of Human Immunodeficiency Virus (HIV) infection",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Exclusion of hepatitis infection based on the following results and/or criteria: a) Positive hepatitis B surface antigen (HepBsAg) (indicative of chronic Hepatitis B or recent acute hepatitis B) b) Negative HepBsAg with a positive for hepatitis B core antibody (Hepatitis B core antibody testing is not required for screening, however if this is done and is positive, then hepatitis B surface antibody [Anti-HBs] testing is necessary. Undetectable anti-HBs in this setting would suggest unclear and possible infection, and needs exclusion). c) Positive Hepatitis C virus antibody: Hepatitis C virus RNA by polymerase chain reaction is necessary. Detectable Hepatitis C virus RNA renders the subject ineligible. If above antibody/antigen testing is not able to be obtained, positive hepatitis B or C viral load",
      "quote": "Positive hepatitis B surface antigen (HepBsAg)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Malignancy other than NSCLC within 3 years prior to randomization, with the exception of those with a negligible risk of metastases or death and treated with expected curative outcome (such as adequately treated carcinoma in situ of the cervix, basal cell carcinoma, cutaneous squamous cell carcinoma, localized prostate cancer treated with curative intent, or ductal carcinoma in situ treated surgically with curative intent).",
      "quote": "Malignancy other than NSCLC within 3 years prior to randomization",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Major surgery within 28 days of study day 1",
      "quote": "Major surgery within 28 days of study day 1",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Significant gastrointestinal disorder that results in significant malabsorption, requirement for intravenous alimentation, or inability to take oral medication.",
      "quote": "Significant gastrointestinal disorder that results in significant malabsorption, requirement for intravenous alimentation, or inability to take oral medication.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Significant cardiovascular disease, such as New York Heart Association cardiac disease (Class II or greater), myocardial infarction within 6 months prior to study day 1, unstable arrhythmias or unstable angina.",
      "quote": "Significant cardiovascular disease, such as New York Heart Association cardiac disease (Class II or greater)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Severe infections within 4 weeks prior to randomization including, but not limited to hospitalization for complications of infection, bacteremia or severe pneumonia.",
      "quote": "Severe infections within 4 weeks prior to randomization",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Therapeutic oral or intravenous antibiotics within 2 weeks prior to randomization. Prophylactic antibiotics are allowed with Amgen medical monitor approval.",
      "quote": "Therapeutic oral or intravenous antibiotics within 2 weeks prior to randomization.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Current CTCAE version 5.0 grade ≥ 2 peripheral neuropathy",
      "quote": "Current CTCAE version 5.0 grade ≥ 2 peripheral neuropathy",
      "thresholds": [
        {
          "test": "peripheral neuropathy grade",
          "op": ">=",
          "value": 2,
          "unit": null
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Unresolved toxicities from prior anti-tumor therapy, defined as not having resolved to CTCAE version 5.0 grade 0 or 1, or to levels dictated in the eligibility criteria with the exception of alopecia (any grade allowed) or toxicities from prior anti-tumor therapy that are considered irreversible (defined as having been present and stable for > 6 months), endocrine adverse events that are stably maintained on appropriate replacement therapy.",
      "quote": "Unresolved toxicities from prior anti-tumor therapy, defined as not having resolved to CTCAE version 5.0 grade 0 or 1",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Anti-tumor therapy (chemotherapy, antibody therapy, molecular targeted therapy, retinoid therapy, hormonal therapy [except for subjects with history of completely resected breast cancer with no active disease for over 3 years on long term adjuvant endocrine therapy], or investigational agent) within 4 weeks of study day 1; Please note that bisphosphonates or anti-Receptor Activator of Nuclear Factor Kappa Beta Ligand (anti-RANKL) antibody therapy is allowed if needed for management of hypercalcemia or for prevention of skeletal events.",
      "quote": "Anti-tumor therapy (chemotherapy, antibody therapy, molecular targeted therapy, retinoid therapy, hormonal therapy ...) within 4 weeks of study day 1",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Therapeutic or palliative radiation therapy within 2 weeks of study day 1. Subjects must have recovered from all radiotherapy related toxicity to CTCAE version 5.0 grade 1 or less with the exception of alopecia (any grade of alopecia allowed).",
      "quote": "Therapeutic or palliative radiation therapy within 2 weeks of study day 1.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Other investigational procedures are excluded",
      "quote": "Other investigational procedures are excluded",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Previous treatment with AMG 510 or other KRAS G12C inhibitor",
      "quote": "Previous treatment with AMG 510 or other KRAS G12C inhibitor",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of severe hypersensitivity to docetaxel or to other drugs formulated with polysorbate 80, or known sensitivity to any of the products or components to be administered during dosing.",
      "quote": "History of severe hypersensitivity to docetaxel or to other drugs formulated with polysorbate 80",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Use of known cytochrome P450 (CYP) 3A4 or P-gp sensitive substrates (with a narrow therapeutic window), within 14 days or 5 half-lives of the drug or its major active metabolite, whichever is longer, prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor.",
      "quote": "Use of known cytochrome P450 (CYP) 3A4 or P-gp sensitive substrates (with a narrow therapeutic window)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Use of strong inducers of CYP3A4 (including herbal supplements such as St. John’s wort) within 14 days or 5 half-lives (whichever is longer) prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor.",
      "quote": "Use of strong inducers of CYP3A4 (including herbal supplements such as St. John’s wort)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Use of warfarin. Other anticoagulation may be allowed with Amgen medical monitor approval",
      "quote": "Use of warfarin.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Currently enrolled in another investigational device or drug study, or less than 4 weeks since ending another investigational device or drug(s), or receiving other investigational agent(s)",
      "quote": "Currently enrolled in another investigational device or drug study",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Female subject is pregnant or breastfeeding or planning to become pregnant or breastfeed during treatment and for an additional 7 days after the last dose of AMG 510 or during treatment with docetaxel and 6 months after last dose of docetaxel if planning to become pregnant.",
      "quote": "Female subject is pregnant or breastfeeding or planning to become pregnant or breastfeed during treatment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Female subjects of childbearing potential unwilling to use 1 highly effective method of contraception during treatment and for an additional 7 days after the last dose of AMG 510 and 6 months after the last dose of docetaxel.",
      "quote": "Female subjects of childbearing potential unwilling to use 1 highly effective method of contraception",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Female subjects of childbearing potential with a positive pregnancy test assessed at Screening or day 1 by a serum pregnancy test and/or urine pregnancy test.",
      "quote": "Female subjects of childbearing potential with a positive pregnancy test",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Male subjects with a female partner of childbearing potential who are unwilling to practice sexual abstinence (refrain from heterosexual intercourse) or use contraception during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product.",
      "quote": "Male subjects with a female partner of childbearing potential who are unwilling to practice sexual abstinence",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Male subjects with a pregnant partner who are unwilling to practice abstinence or use a condom during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product.",
      "quote": "Male subjects with a pregnant partner who are unwilling to practice abstinence or use a condom",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Male subjects unwilling to abstain from donating sperm during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product.",
      "quote": "Male subjects unwilling to abstain from donating sperm",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Subject likely to not be available to complete all protocol-required study visits or procedures, and/or to comply with all required study procedures (eg, Clinical Outcome Assessments) to the best of the subject and investigator’s knowledge.",
      "quote": "Subject likely to not be available to complete all protocol-required study visits or procedures",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History or evidence of any other clinically significant disorder, condition or disease (with the exception of those outlined above) that, in the opinion of the investigator or Amgen physician, if consulted, would pose a risk to subject safety or interfere with the study evaluation, procedures or completion, or interpretation of results.",
      "quote": "History or evidence of any other clinically significant disorder, condition or disease",
      "thresholds": []
    }
  ]
}
